using System;using System.IO;using System.Text;using System.Text.RegularExpressions;using System.Web.Script.Serialization;using System.Collections.Generic;using System.Diagnostics;
class IrisDownloadHost {
    static bool ReadExact(Stream stream,byte[] bytes){int offset=0;while(offset<bytes.Length){int n=stream.Read(bytes,offset,bytes.Length-offset);if(n==0)return false;offset+=n;}return true;}
    static void WriteLinkReceipt(string directory,string source,JavaScriptSerializer json){string file=Path.Combine(directory,"link-"+source+".json"),temp=file+"."+Guid.NewGuid().ToString("N")+".tmp";try{File.WriteAllText(temp,json.Serialize(new{source=source,utc=DateTime.UtcNow.ToString("o")}),Encoding.UTF8);if(File.Exists(file))File.Replace(temp,file,null);else File.Move(temp,file);}catch{}finally{try{if(File.Exists(temp))File.Delete(temp);}catch{}}}
    static int Main(string[] args){bool qa=Array.IndexOf(args,"--qa")>=0;string directory=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,qa?"Data-qa":"Data","BrowserDownloads");string file=Path.Combine(directory,"browser-"+Process.GetCurrentProcess().Id+".json");try{
        if(!qa){
            string id=File.ReadAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"BrowserExtension","extension-id.txt")).Trim();
            if(args.Length==0||!Regex.IsMatch(id,@"^[a-p]{32}$")||args[0]!="chrome-extension://"+id+"/")return 2;
        }
        var json=new JavaScriptSerializer{MaxJsonLength=65536,RecursionLimit=12};using(var input=Console.OpenStandardInput())using(var output=Console.OpenStandardOutput()){var size=new byte[4];while(ReadExact(input,size)){uint length=BitConverter.ToUInt32(size,0);if(length==0||length>65536)return 3;var bytes=new byte[length];if(!ReadExact(input,bytes))return 4;var payload=json.DeserializeObject(Encoding.UTF8.GetString(bytes)) as Dictionary<string,object>;object itemsObject,sourceObject;if(payload==null||!payload.TryGetValue("items",out itemsObject)||!payload.TryGetValue("source",out sourceObject))return 5;string source=Convert.ToString(sourceObject);if(source!="Chrome"&&source!="Edge")return 6;var items=itemsObject as object[];if(items==null||items.Length>64)return 7;var safe=new List<object>();foreach(var obj in items){var item=obj as Dictionary<string,object>;if(item==null)return 8;string name=Path.GetFileName(Convert.ToString(item["name"]));if(name.Length>100)name=name.Substring(0,100);if(name.IndexOfAny(new[]{'\r','\n','\0'})>=0)return 9;double received=Convert.ToDouble(item["received"]),total=Convert.ToDouble(item["total"]);if(double.IsNaN(received)||double.IsInfinity(received)||double.IsNaN(total)||double.IsInfinity(total)||received<0||total< -1||received>1e16||total>1e16)return 10;safe.Add(new{name=name,received=received,total=total});}
            Directory.CreateDirectory(directory);string temp=file+".tmp";File.WriteAllText(temp,json.Serialize(new{source=source,utc=DateTime.UtcNow.ToString("o"),items=safe}),Encoding.UTF8);if(File.Exists(file))File.Replace(temp,file,null);else File.Move(temp,file);WriteLinkReceipt(directory,source,json);var ack=Encoding.UTF8.GetBytes("{\"ok\":true}");output.Write(BitConverter.GetBytes(ack.Length),0,4);output.Write(ack,0,ack.Length);output.Flush();}}
        return 0;
    }catch{return 1;}finally{try{if(File.Exists(file))File.Delete(file);if(File.Exists(file+".tmp"))File.Delete(file+".tmp");}catch{}}}
}
